            const newId = (prev.length > 0 ? Math.max(...prev.map(r => r.id)) : 0) + 1;
            return [...prev, { ...newRoleData, id: newId }];
        });
    } else {
        setSuperUserRoles(prev => {
            const newId = (prev.length > 0 ? Math.max(...prev.map(r => r.id)) : 100) + 1;
            return [...prev, { ...newRoleData, id: newId }];
        });
    }
  };

  const handleSaveChanges = () => {
