                  {shopPermissions.map(p => <th key={p.role} scope="col" className={`px-6 py-3 text-center text-xs font-medium uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{p.role}</th>)}
