    <content><![CDATA[
import React, { useState, useEffect } from 'react';
import Icon, { IconName } from './Icon';
import { Theme, ActiveView } from '../types';
import ThemeSwitch from './ThemeSwitch';
import { useTranslation } from '../contexts/LanguageContext';

interface SidebarProps {
    theme: Theme;
    toggleTheme: () => void;
    activeView: ActiveView;
    onNavigate: (view: ActiveView) => void;
    isCollapsed: boolean;
    allowCalls: boolean;
}

interface NavLinkProps {
  icon: IconName;
  label: string;
  active?: boolean;
  theme: Theme;
  onClick?: () => void;
  isCollapsed: boolean;
}

const NavLink: React.FC<NavLinkProps> = ({ icon, label, active = false, theme, onClick, isCollapsed }) => {
  const activeClasses = 'bg-yellow-500 text-slate-900';
  const inactiveClasses = theme === 'dark' 
    ? 'text-slate-300 hover:bg-slate-700 hover:text-white'
    : 'text-slate-600 hover:bg-slate-200 hover:text-slate-900';

  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center text-sm font-medium rounded-md transition-colors text-left relative group ${isCollapsed ? 'justify-center p-2.5' : 'px-4 py-2.5'} ${
        active ? activeClasses : inactiveClasses
      }`}
      aria-label={isCollapsed ? label : undefined}
    >
      <Icon name={icon} className="h-5 w-5 flex-shrink-0" />
      <span className={`whitespace-nowrap transition-all duration-200 ${isCollapsed ? 'w-0 ml-0 opacity-0' : 'w-auto ml-3 opacity-100'}`}>{label}</span>
      {isCollapsed && (
        <span className="absolute left-full ml-3 px-2 py-1 text-xs font-semibold text-white bg-slate-800 rounded-md shadow-lg opacity-0 group-hover:opacity-100 transition-opacity duration-200 whitespace-nowrap z-50 pointer-events-none">
          {label}
        </span>
      )}
    </button>
  );
};

const SectionTitle: React.FC<{ theme: Theme; children: React.ReactNode, isCollapsed: boolean }> = ({ theme, children, isCollapsed }) => {
    if (isCollapsed) {
        return <hr className={`my-4 border-t ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`} />;
    }
    return <h3 className={`px-4 mt-6 mb-2 text-xs font-semibold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>{children}</h3>;
}

const Sidebar: React.FC<SidebarProps> = ({ theme, toggleTheme, activeView, onNavigate, isCollapsed, allowCalls }) => {
  const { t } = useTranslation();

  // Active states for collapsible menus
  const isDashboardMenuActive = ['dashboard', 'dashboard-users', 'dashboard-system', 'dashboard-traffic'].includes(activeView);
  const isStockMenuActive = ['stock-listing', 'stock-purchase'].includes(activeView);
  const isAccountMenuActive = ['profile', 'settings'].includes(activeView);
  const isUserMenuActive = ['shop-users', 'super-users', 'permissions', 'roles'].includes(activeView);
  const isShopMgtMenuActive = ['shops', 'shop-profile', 'shop-surveillance'].includes(activeView);
  const isFinancesMenuActive = ['finances-income-statement', 'finances-balance-sheet', 'finances-cash-flow'].includes(activeView);
  const isCountriesMgtMenuActive = ['countries', 'country-admin-levels'].includes(activeView);
  const isSystemSettingsMenuActive = ['settings-cameras', 'settings-api', 'system-message-settings', 'settings-calls'].includes(activeView);
  const isReportsMenuActive = ['reports-messages', 'reports-calls', 'reports-daily-sales'].includes(activeView);
  const isClientMgtMenuActive = ['client-list'].includes(activeView);


  // State for menu open/closed status
  const [isDashboardMenuOpen, setIsDashboardMenuOpen] = useState(isDashboardMenuActive);
  const [isStockMenuOpen, setIsStockMenuOpen] = useState(isStockMenuActive);
  const [isAccountMenuOpen, setIsAccountMenuOpen] = useState(isAccountMenuActive);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(isUserMenuActive);
  const [isShopMgtMenuOpen, setIsShopMgtMenuOpen] = useState(isShopMgtMenuActive);
  const [isFinancesMenuOpen, setIsFinancesMenuOpen] = useState(isFinancesMenuActive);
  const [isCountriesMgtMenuOpen, setIsCountriesMgtMenuOpen] = useState(isCountriesMgtMenuActive);
  const [isSystemSettingsMenuOpen, setIsSystemSettingsMenuOpen] = useState(isSystemSettingsMenuActive);
  const [isReportsMenuOpen, setIsReportsMenuOpen] = useState(isReportsMenuActive);
  const [isClientMgtMenuOpen, setIsClientMgtMenuOpen] = useState(isClientMgtMenuActive);


  // Effect to auto-open active menu
  useEffect(() => { if (isDashboardMenuActive) setIsDashboardMenuOpen(true); }, [isDashboardMenuActive]);
  useEffect(() => { if (isStockMenuActive) setIsStockMenuOpen(true); }, [isStockMenuActive]);
  useEffect(() => { if (isAccountMenuActive) setIsAccountMenuOpen(true); }, [isAccountMenuActive]);
  useEffect(() => { if (isUserMenuActive) setIsUserMenuOpen(true); }, [isUserMenuActive]);
  useEffect(() => { if (isShopMgtMenuActive) setIsShopMgtMenuOpen(true); }, [isShopMgtMenuActive]);
  useEffect(() => { if (isFinancesMenuActive) setIsFinancesMenuOpen(true); }, [isFinancesMenuActive]);
  useEffect(() => { if (isCountriesMgtMenuActive) setIsCountriesMgtMenuOpen(true); }, [isCountriesMgtMenuActive]);
  useEffect(() => { if (isSystemSettingsMenuActive) setIsSystemSettingsMenuOpen(true); }, [isSystemSettingsMenuActive]);
  useEffect(() => { if (isReportsMenuActive) setIsReportsMenuOpen(true); }, [isReportsMenuActive]);
  useEffect(() => { if (isClientMgtMenuActive) setIsClientMgtMenuOpen(true); }, [isClientMgtMenuActive]);


  return (
    <aside className={`flex-shrink-0 flex flex-col p-4 transition-all duration-300 ease-in-out ${isCollapsed ? 'w-20' : 'w-64'} ${theme === 'dark' ? 'bg-slate-900 text-white' : 'bg-white text-slate-800 border-r border-slate-200'}`}>
      <div className={`flex items-center space-x-3 mb-6 flex-shrink-0 transition-all duration-300 ${isCollapsed ? 'justify-center space-x-0' : 'px-2'}`}>
        <div className="w-8 h-8 bg-yellow-500 flex-shrink-0"></div>
        <span className={`text-xl font-bold whitespace-nowrap transition-all duration-200 ${isCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'} ${theme === 'dark' ? 'text-white' : 'text-slate-900'}`}>Duqact</span>
      </div>
      <nav className={`flex-1 space-y-1 overflow-y-auto overflow-x-hidden ${isCollapsed ? '' : 'pr-2'}`}>
        {/* Collapsible Dashboard Menu */}
        <div>
            <button onClick={() => isCollapsed ? onNavigate('dashboard-users') : setIsDashboardMenuOpen(!isDashboardMenuOpen)} className={`w-full flex items-center justify-between text-sm font-medium rounded-md transition-colors text-left relative group ${isCollapsed ? 'p-2.5 justify-center' : 'px-4 py-2.5'} ${isDashboardMenuActive ? 'bg-yellow-500 text-slate-900' : (theme === 'dark' ? 'text-slate-300 hover:bg-slate-700 hover:text-white' : 'text-slate-600 hover:bg-slate-200 hover:text-slate-900')}`}>
                <div className="flex items-center"><Icon name="dashboard" className="h-5 w-5 flex-shrink-0" /><span className={`whitespace-nowrap transition-all duration-200 ${isCollapsed ? 'w-0 ml-0 opacity-0' : 'w-auto ml-3 opacity-100'}`}>{t('sidebar.dashboard', 'Dashboard')}</span></div>
                <Icon name="chevron-down" className={`h-4 w-4 transition-all duration-200 ${isDashboardMenuOpen ? 'rotate-180' : ''} ${isCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'}`} />
            </button>
            <div className={`overflow-hidden transition-all duration-300 ease-in-out ${isDashboardMenuOpen && !isCollapsed ? 'max-h-60' : 'max-h-0'}`}>
                <div className={`pt-1 space-y-1 ${isCollapsed ? 'hidden' : 'pl-4'}`}>
                    <NavLink isCollapsed={isCollapsed} theme={theme} icon="user-mgt" label={t('sidebar.usersData', 'Users Data')} active={['dashboard', 'dashboard-users'].includes(activeView)} onClick={() => onNavigate('dashboard-users')} />
                    <NavLink isCollapsed={isCollapsed} theme={theme} icon="reports" label={t('sidebar.trafficData', 'Traffic Data')} active={activeView === 'dashboard-traffic'} onClick={() => onNavigate('dashboard-traffic')} />
                    <NavLink isCollapsed={isCollapsed} theme={theme} icon="system-settings" label={t('sidebar.systemUsage', 'System Usage')} active={activeView === 'dashboard-system'} onClick={() => onNavigate('dashboard-system')} />
                </div>
            </div>
        </div>

        <NavLink isCollapsed={isCollapsed} theme={theme} icon="sales-desk" label={t('sidebar.salesDesk', 'Sales Desk')} />

        <SectionTitle theme={theme} isCollapsed={isCollapsed}>{t('sidebar.shopManagement', 'Shop Management')}</SectionTitle>

        {/* Reports Menu */}
        <div>
            <button onClick={() => isCollapsed ? onNavigate('reports-messages') : setIsReportsMenuOpen(!isReportsMenuOpen)} className={`w-full flex items-center justify-between text-sm font-medium rounded-md transition-colors text-left relative group ${isCollapsed ? 'p-2.5 justify-center' : 'px-4 py-2.5'} ${isReportsMenuActive ? 'bg-yellow-500 text-slate-900' : (theme === 'dark' ? 'text-slate-300 hover:bg-slate-700 hover:text-white' : 'text-slate-600 hover:bg-slate-200 hover:text-slate-900')}`}>
                <div className="flex items-center"><Icon name="reports" className="h-5 w-5 flex-shrink-0" /><span className={`whitespace-nowrap transition-all duration-200 ${isCollapsed ? 'w-0 ml-0 opacity-0' : 'w-auto ml-3 opacity-100'}`}>{t('sidebar.reports', 'Reports')}</span></div>
                <Icon name="chevron-down" className={`h-4 w-4 transition-all duration-200 ${isReportsMenuOpen ? 'rotate-180' : ''} ${isCollapsed ? 'w-0 opacity-0' : 'w-auto opacity-100'}`} />
            </button>
            <div className={`overflow-hidden transition-all duration-300 ease-in-out ${isReportsMenuOpen && !isCollapsed ? 'max-h-60' : 'max-h-0'}`}>
                <div className={`pt-1 space-y-1 ${isCollapsed ? 'hidden' : 'pl-4'}`}>
                     <NavLink isCollapsed={isCollapsed} theme={theme} icon="cash" label={t('sidebar.dailySales', 'Daily Sales')} active={activeView === 'reports-daily-sales'} onClick={() => onNavigate('reports-daily-sales')} />
                     <NavLink isCollapsed={isCollapsed} theme={theme} icon="chat-bubble" label="Messages" active={activeView === 'reports-messages'} onClick={() => onNavigate('reports-messages')} />
                     {allowCalls && <NavLink isCollapsed={isCollapsed} theme={theme} icon="phone" label="Calls" active={activeView === 'reports-calls'} onClick={() => onNavigate('reports-calls')} />}
