                <div className="flex items-center"><Icon name="client-mgt" className="h-5 w-5 flex-shrink-0" /><span className={`whitespace-nowrap transition-all duration-200 ${isCollapsed ? 'w-0 ml-0 opacity-0' : 'w-auto ml-3 opacity-100'}`}>{t('sidebar.clientMgt', 'Client mgt')}</span></div>
