  allowMicrophone: boolean;
  setAllowMicrophone: React.Dispatch<React.SetStateAction<boolean>>;
}

const MainContent: React.FC<MainContentProps> = ({ 
  theme, 
  activeView, 
  user, 
  setUser, 
  onNavigate, 
  language, 
  setLanguage,
  verificationRequests,
  setVerificationRequests,
  shopRoles,
  setShopRoles,
  superUserRoles,
  setSuperUserRoles,
  shopUsers,
  setShopUsers,
  currentUser,
  selectedShop,
  setSelectedShop,
  onToggleSidebar,
  countries,
