    'dashboard-traffic': t('header.title.dashboardTraffic', 'Traffic Dashboard'),
    'stock-purchase': t('header.title.stockPurchase', 'Shop Purchases'),
    profile: t('header.title.profile', 'My Profile'),
    settings: t('header.title.settings', 'Account Settings'),
