  | 'manageShops' 
  | 'viewGlobalReports' 
  | 'systemConfiguration' 
  | 'manageBilling'
  | 'phone_access'
  | 'camera_access'
  | 'personality_view'
  | 'personality_edit'
  | 'profile_edit'
  | 'finances_income'
