    role: string;
    permissions: Record<PermissionKey, boolean>;
}

export interface SuperUserRolePermissionSet {
    role: string;
    permissions: Record<SuperUserPermissionKey, boolean>;
}

export type LeadStatus = 'New' | 'Contacted' | 'Qualified' | 'Lost';

export interface Lead {
  id: number;
  companyName: string;
  status: LeadStatus;
  source: 'Website' | 'Referral' | 'Cold Call';
  createdDate: string; // ISO date string
}

export interface Client {
    id: number;
    name: string;
    phone: string;
    email: string;
    location: string;
    status: 'Active' | 'Inactive';
    lastOrderDate: string;
}

export interface CallRecord {
    id: string;
    clientName: string;
    phoneNumber: string;
    type: 'Inbound' | 'Outbound' | 'Missed';
    duration: number; // in seconds
    timestamp: string; // ISO date
    status: 'Completed' | 'Missed' | 'Voicemail';
    recordingUrl?: string; // Mock URL
    transcription?: string;
}

export interface DeletedCallRecord extends CallRecord {
    deletedAt: string;
    deletedBy: string;
    deletionReason: string;
}

export interface InventoryProduct {
  id: string;
  name: string;
  stockLevel: number;
  reorderPoint: number;
  supplier: string;
}

export interface Notification {
  id: string;
  type: 'low_stock' | 'system_update' | 'new_message';
  priority: 'high' | 'medium' | 'low';
  message: string;
  timestamp: string; // ISO date string
  read: boolean;
  productId?: string;
}

export type DeviceType = 'Camera' | 'DVR' | 'NVR';
export type ConnectionStatus = 'Pending' | 'Approved' | 'Offline' | 'Error' | 'Deleted';

export interface CameraDevice {
    id: number;
    name: string;
    type: DeviceType;
    connectionString: string; // IP or URL
    shopId: number;
    shopName: string; // Cached for display
    category: 'Entrances' | 'Checkout' | 'Aisles' | 'Storage' | 'Outside' | 'Other';
    status: ConnectionStatus;
    ownerIdForOtp?: number;
    isLive?: boolean; // Frontend state for simulation
    addedAt: string;
    channels?: number;
    deletionRemarks?: string;
    deletedAt?: string;
    deletedBy?: string;
    restorationRemarks?: string;
    restoredAt?: string;
    restoredBy?: string;
}

export interface ApiConnection {
    id: number;
    name: string;
    endpoint: string;
    apiKey: string; // Should be masked in UI
    status: 'Active' | 'Inactive';
    description: string;
    createdAt: string;
}

export interface ChatMessage {
    id: string;
    senderId: number;
    senderName: string;
    senderRole: string;
    shopId?: number;
    shopName?: string;
    content: string;
    timestamp: string;
    roomId: string;
}

export interface ChatRoom {
    id: string;
    name: string;
    type: 'General' | 'Shop' | 'Region' | 'Private';
}

export interface MessageAssignment {
    superUserId: number;
    assignedShopIds: number[];
    assignedAdminLevels: { countryCode: string; level: number; name: string }[];
}

export interface CallGateway {
    id: number;
    name: string;
    host: string;
    port: number;
    protocol: 'SIP' | 'IAX2';
    apiKey?: string;
    status: 'Active' | 'Inactive';
    createdAt: string;
    createdBy: string;
}
