  const isShopMgtMenuActive = ['shops', 'shop-profile', 'shop-surveillance'].includes(activeView);
  const isFinancesMenuActive = ['finances-income-statement', 'finances-balance-sheet', 'finances-cash-flow'].includes(activeView);
  const isCountriesMgtMenuActive = ['countries', 'country-admin-levels'].includes(activeView);
  const isSystemSettingsMenuActive = ['settings-cameras', 'settings-api', 'system-message-settings', 'settings-calls'].includes(activeView);
  const isReportsMenuActive = ['reports-messages', 'reports-calls', 'reports-daily-sales'].includes(activeView);
  const isClientMgtMenuActive = ['client-list'].includes(activeView);


  // State for menu open/closed status
