    const itemsPerPage = 10;

    // Metrics
    const totalTxns = 58684;
    const totalSales = 1882849566.54;
    const totalCapital = 1040328951;
    const totalIncome = 842520615;

    // Mock Filters State (just UI placeholders)
    const [filters, setFilters] = useState({
        shop: '',
        user: '',
        product: '',
        client: '',
        paymentMode: '',
        status: '',
        startDate: '',
        endDate: '',
        country: ''
    });

    const filteredData = useMemo(() => {
        return mockDailySales.filter(item => 
            item.productName.toLowerCase().includes(searchTerm.toLowerCase()) ||
            item.receiptNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
            item.shopName.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [searchTerm]);

    const handleResetFilters = () => {
        setFilters({
            shop: '', user: '', product: '', client: '', paymentMode: '', status: '', startDate: '', endDate: '', country: ''
        });
        setSearchTerm('');
    };

    const formatDate = (dateStr: string) => {
        const date = new Date(dateStr);
        return date.toLocaleString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric', hour12: true });
    };

    const formatCurrency = (amount: number) => `UGX ${amount.toLocaleString()}`;

    const inputClass = `w-full text-sm px-3 py-2 border rounded-md focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-700'}`;
    const labelClass = `block text-xs font-medium mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`;

    return (
        <div className="space-y-6">
            {/* Top Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Txns" value={totalTxns.toLocaleString()} icon="stock-listing" theme={theme} />
                <StatCard label="Sales" value={totalSales.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} icon="cash" theme={theme} />
                <StatCard label="Capital" value={totalCapital.toLocaleString()} icon="finances" theme={theme} />
                <StatCard label="Income" value={totalIncome.toLocaleString()} icon="reports" theme={theme} />
            </div>

            {/* Filter Section */}
            <div className={`${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'} rounded-lg shadow-sm border p-4`}>
                <div className="mb-4 pb-2 border-b border-gray-200 dark:border-gray-700 font-semibold text-sm">Filter</div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div><label className={labelClass}>Shop</label><select className={inputClass} value={filters.shop} onChange={e => setFilters({...filters, shop: e.target.value})}><option>Select Shop</option></select></div>
                    <div><label className={labelClass}>User</label><select className={inputClass} value={filters.user} onChange={e => setFilters({...filters, user: e.target.value})}><option>Select user</option></select></div>
                    <div><label className={labelClass}>Product</label><select className={inputClass} value={filters.product} onChange={e => setFilters({...filters, product: e.target.value})}><option>Select product</option></select></div>
                    <div><label className={labelClass}>Client</label><select className={inputClass} value={filters.client} onChange={e => setFilters({...filters, client: e.target.value})}><option>Select Client</option></select></div>
                    <div><label className={labelClass}>Payment Mode</label><select className={inputClass} value={filters.paymentMode} onChange={e => setFilters({...filters, paymentMode: e.target.value})}><option>Payment mode</option></select></div>
                    <div><label className={labelClass}>Status</label><select className={inputClass} value={filters.status} onChange={e => setFilters({...filters, status: e.target.value})}><option>Select status</option></select></div>
                    <div><label className={labelClass}>Start Date</label><input type="date" className={inputClass} value={filters.startDate} onChange={e => setFilters({...filters, startDate: e.target.value})} /></div>
                    <div><label className={labelClass}>End Date</label><input type="date" className={inputClass} value={filters.endDate} onChange={e => setFilters({...filters, endDate: e.target.value})} /></div>
                    <div><label className={labelClass}>Country</label><select className={inputClass} value={filters.country} onChange={e => setFilters({...filters, country: e.target.value})}><option>Select Country</option></select></div>
                </div>
                <div className="flex justify-end space-x-2 mt-4">
                    <button onClick={handleResetFilters} className={`px-4 py-2 text-sm font-medium border rounded-md ${theme === 'dark' ? 'border-slate-600 text-slate-300 hover:bg-slate-800' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}>
                        <Icon name="x-mark" className="h-4 w-4 inline mr-1"/> Clear
                    </button>
                    <button className="px-4 py-2 text-sm font-medium bg-black text-white rounded-md hover:bg-gray-800 flex items-center">
                        <Icon name="filter" className="h-4 w-4 mr-1"/> Filter
                    </button>
                </div>
            </div>

            {/* Data Table */}
            <div className={`${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'} rounded-lg shadow-sm border`}>
                <div className="p-4 flex justify-between items-center border-b border-gray-200 dark:border-gray-700">
                    <h3 className={`font-bold text-lg ${theme === 'dark' ? 'text-slate-100' : 'text-slate-800'}`}>Shop Sales</h3>
                    <div className="relative">
                        <Icon name="search" className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                        <input 
                            type="text" 
                            placeholder="Search..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className={`pl-9 pr-3 py-1.5 text-sm border rounded-md focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-700'}`}
                        />
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className={`min-w-full divide-y ${theme === 'dark' ? 'divide-slate-700' : 'divide-slate-200'}`}>
                        <thead className={theme === 'dark' ? 'bg-slate-800' : 'bg-slate-50'}>
                            <tr>
                                {['#', 'RN', 'TN', 'Transaction', 'Qty', 'Paid', 'Amount', 'Income', 'Shop', 'Created by', 'Sold on', 'Actions'].map((header) => (
                                    <th key={header} scope="col" className={`px-4 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}>
                                        {header}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody className={`divide-y ${theme === 'dark' ? 'bg-slate-900 divide-slate-700' : 'bg-white divide-slate-200'}`}>
                            {filteredData.map((row) => (
                                <tr key={row.id} className={theme === 'dark' ? 'hover:bg-slate-800/50' : 'hover:bg-slate-50'}>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{row.id}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{row.receiptNumber}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs text-center ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{row.transactionNumber}</td>
                                    <td className="px-4 py-3 text-xs">
                                        <div className={`font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{row.productName}</div>
                                        <div className={`mt-0.5 ${theme === 'dark' ? 'text-slate-500' : 'text-slate-500'}`}>{row.productDetails}</div>
                                    </td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs text-center ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{row.qty}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{formatCurrency(row.paid)}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs font-semibold ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{formatCurrency(row.amount)}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{formatCurrency(row.income)}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{row.shopName}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{row.createdBy}</td>
                                    <td className={`px-4 py-3 whitespace-nowrap text-xs ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>
                                        {formatDate(row.soldOn).split(', ').map((part, i) => <div key={i}>{part}</div>)}
                                    </td>
                                    <td className="px-4 py-3 whitespace-nowrap text-xs">
                                        <div className="flex items-center space-x-2">
                                            <button className="text-blue-500 hover:text-blue-600"><Icon name="print" className="h-4 w-4" /></button>
                                            <button className="text-blue-500 hover:text-blue-600"><Icon name="edit" className="h-4 w-4" /></button>
                                            <button className="text-red-500 hover:text-red-600"><Icon name="delete" className="h-4 w-4" /></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div className="p-4 flex justify-between items-center text-xs border-t border-gray-200 dark:border-gray-700">
                    <div className={theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}>
                        Showing 1 to {itemsPerPage} of {totalTxns.toLocaleString()} records
                    </div>
                    <div className="flex space-x-1">
                        <button className={`p-1 rounded ${theme === 'dark' ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-500'}`}><Icon name="chevron-left" className="h-4 w-4" /></button>
                        <button className="px-2 py-1 bg-yellow-500 text-slate-900 font-bold rounded">1</button>
                        <button className={`px-2 py-1 rounded ${theme === 'dark' ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-600'}`}>2</button>
                        <button className={`px-2 py-1 rounded ${theme === 'dark' ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-600'}`}>3</button>
                        <button className={`px-2 py-1 rounded ${theme === 'dark' ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-600'}`}>4</button>
                        <button className={`px-2 py-1 rounded ${theme === 'dark' ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-600'}`}>5</button>
                        <button className={`p-1 rounded ${theme === 'dark' ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-500'}`}><Icon name="chevron-right" className="h-4 w-4" /></button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DailySalesPage;
]]></content>
</change>
